"""Vault recipe notes: one Markdown note per recipe under <vault>/Recipes/.

A note, top to bottom:
    frontmatter                  the Recipes.base views read it; Alex edits it
    free text                    an optional description
    ## Ingredients               generated from the data block
    ## Method                    generated
    ## Cooking for Engineers     generated (an HTML table from recipe_grid)
    ## Nutrition                 generated by `recipe nutrition`
    ## Notes                     free text; the Console card shows it
    ## Cook log                  `recipe cooked` appends a line
    > [!abstract]- Recipe data   the canonical JSON: ingredients, steps, cfe,
                                 nutrition overrides, and the section hashes

INVARIANTS:
- Only the generated sections and the data block are rewritten. Every other
  line of the note stays as it was.
- A generated section is rewritten only while its text still hashes to the
  value recorded at the last write. Otherwise it holds a hand edit, and the
  write stops with HandEdit until `recipe adopt` takes the edit into the data
  or the caller passes force.
- Frontmatter is read from disk on every command and keeps its key order.
- PyYAML loads lazily, so the section logic imports without it.
"""

from __future__ import annotations

import datetime as dt
import hashlib
import json
import os
import re
import tempfile
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from . import model

VAULT = Path(os.environ.get("VAULT_DIR") or Path.home() / "Exobrain")
RECIPES = Path(os.environ.get("RECIPES_DIR") or VAULT / "Recipes")

GENERATED = ("Ingredients", "Method", "Cooking for Engineers", "Nutrition")
RENDERED = ("Ingredients", "Method", "Cooking for Engineers")   # what render() rebuilds
ORDER = ("Ingredients", "Method", "Cooking for Engineers", "Nutrition", "Notes", "Cook log")
DATA_TITLE = "Recipe data"
LIST_BREAK = "<!-- -->"          # ends a Markdown list between two ingredient groups; hidden in reading view
NO_COOKS = "_No cooks logged yet._"
DATA_HINT = "The sections above are built from this block. Change it through /recipes (`recipe put`), then `recipe render`."
FM_ORDER = (
    "type", "course", "cuisine", "status", "rating", "servings", "yield", "prep_min", "cook_min", "total_min",
    "vegan", "kcal_serving", "protein_serving", "key_ingredients", "source", "author", "image", "added",
    "last_cooked", "times_cooked", "tags",
)
_FENCE_RE = re.compile(r"^```")


class HandEdit(Exception):
    def __init__(self, sections: list[str]):
        super().__init__("hand edit in: " + ", ".join(sections))
        self.sections = sections


@dataclass
class Section:
    heading: str | None          # None for the text above the first "## " heading
    lines: list[str] = field(default_factory=list)

    @property
    def content(self) -> str:
        return "\n".join(self.lines).strip("\n")


@dataclass
class Note:
    path: Path
    frontmatter: dict[str, Any]
    fm_text: str                 # the raw frontmatter block, kept when unchanged
    sections: list[Section]
    data: dict[str, Any]
    fm_changed: bool = False

    @property
    def title(self) -> str:
        return self.path.stem

    def section(self, heading: str) -> Section | None:
        return next((s for s in self.sections if s.heading == heading), None)


# ---------- hashing and markdown for the generated sections ----------

def digest(text: str) -> str:
    norm = "\n".join(line.rstrip() for line in text.strip("\n").splitlines())
    return hashlib.sha1(norm.encode("utf-8")).hexdigest()[:12]


def ingredients_md(ingredients: Any) -> str:
    flat = model.flatten(ingredients)
    out: list[str] = []
    for title, idx in model.groups(ingredients):
        if title:
            if out:
                out.append("")
            out.append(f"**{title}**")
        elif out:
            out += ["", LIST_BREAK, ""]
        out.extend(f"- {flat[i]}" for i in idx)
    return "\n".join(out)


def method_md(steps: Any) -> str:
    out = []
    for n, step in enumerate(steps or [], 1):
        text = step.get("text", "") if isinstance(step, dict) else str(step)
        out.append(f"{n}. {' '.join(str(text).split())}")
    return "\n".join(out)


def cfe_md(recipe: dict[str, Any], table_html) -> str:
    if not recipe.get("cfe"):
        return "_No table yet. Ask MIST to convert this recipe (`/recipes`)._"
    return table_html(recipe)


# ---------- parsing ----------

def _split_frontmatter(text: str) -> tuple[str, str]:
    if text.startswith("---\n"):
        end = text.find("\n---", 4)
        if end != -1:
            close = text.find("\n", end + 4)
            close = len(text) if close == -1 else close + 1
            return text[:close], text[close:]
    return "", text


def _load_yaml(block: str) -> dict[str, Any]:
    if not block:
        return {}
    import yaml  # lazy: PyYAML is a CLI dependency, not a test one

    inner = block.strip()
    inner = inner[3:] if inner.startswith("---") else inner
    inner = inner[: inner.rfind("---")] if inner.endswith("---") else inner
    data = yaml.safe_load(inner) or {}
    return data if isinstance(data, dict) else {}


def _extract_data(lines: list[str]) -> tuple[list[str], dict[str, Any]]:
    """Remove the data callout from the body lines; return (rest, parsed JSON)."""
    for i, line in enumerate(lines):
        if line.startswith("> [!abstract]") and DATA_TITLE in line:
            j = i + 1
            while j < len(lines) and lines[j].startswith(">"):
                j += 1
            inner = [ln[2:] if ln.startswith("> ") else ln[1:] for ln in lines[i + 1 : j]]
            start = next((k for k, ln in enumerate(inner) if ln.strip().startswith("```json")), None)
            data: dict[str, Any] = {}
            if start is not None:
                end = next((k for k in range(start + 1, len(inner)) if _FENCE_RE.match(inner[k].strip())), len(inner))
                parsed = json.loads("\n".join(inner[start + 1 : end]) or "{}")
                data = parsed if isinstance(parsed, dict) else {}
            rest = lines[:i] + lines[j:]
            while rest and (not rest[-1].strip() or rest[-1].strip() == "---"):
                rest.pop()
            return rest, data
    return lines, {}


def _sections(lines: list[str]) -> list[Section]:
    out = [Section(None)]
    in_fence = False
    for line in lines:
        if _FENCE_RE.match(line.strip()):
            in_fence = not in_fence
        if not in_fence and line.startswith("## "):
            out.append(Section(line[3:].strip()))
        else:
            out[-1].lines.append(line)
    return out


def parse(text: str, path: Path) -> Note:
    fm_text, body = _split_frontmatter(text)
    lines = body.split("\n")
    rest, data = _extract_data(lines)
    return Note(path, _load_yaml(fm_text), fm_text, _sections(rest), data)


def read(path: Path) -> Note:
    return parse(path.read_text(encoding="utf-8"), path)


# ---------- writing ----------

def _dump_yaml(fm: dict[str, Any]) -> str:
    import yaml

    class Dumper(yaml.SafeDumper):
        def increase_indent(self, flow: bool = False, indentless: bool = False):  # Obsidian's "  - item" style
            return super().increase_indent(flow, False)

    ordered = {k: fm[k] for k in FM_ORDER if k in fm and fm[k] is not None}
    ordered.update({k: v for k, v in fm.items() if k not in ordered and v is not None})
    text = yaml.dump(ordered, Dumper=Dumper, sort_keys=False, allow_unicode=True,
                     default_flow_style=False, width=4096)
    return "---\n" + text + "---\n"


def _data_block(data: dict[str, Any]) -> list[str]:
    body = json.dumps(data, ensure_ascii=False, indent=2).split("\n")
    return [f"> [!abstract]- {DATA_TITLE}", f"> {DATA_HINT}", "> ```json", *(f"> {ln}" for ln in body), "> ```"]


def serialize(note: Note) -> str:
    if note.fm_changed or not note.fm_text:
        fm = _dump_yaml(note.frontmatter) if note.frontmatter else ""
    else:
        fm = note.fm_text
    chunks: list[str] = []
    for s in note.sections:
        if s.heading is None:
            text = s.content
            if text:
                chunks.append(text)
            continue
        content = s.content
        chunks.append(f"## {s.heading}\n\n{content}" if content else f"## {s.heading}")
    body = "\n\n".join(chunks)
    return fm + body + "\n\n---\n\n" + "\n".join(_data_block(note.data)) + "\n"


def atomic_write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=path.parent, prefix=".recipe-", suffix=".tmp")
    with os.fdopen(fd, "w", encoding="utf-8") as fh:
        fh.write(text)
    os.replace(tmp, path)


def set_section(note: Note, heading: str, content: str, force: bool = False) -> None:
    """Replace (or insert) one generated section; HandEdit if it holds an edit."""
    hashes = note.data.setdefault("_render", {})
    sec = note.section(heading)
    if sec is not None and not force:
        current = digest(sec.content)
        recorded = hashes.get(heading)
        if sec.content.strip() and current != recorded and current != digest(content):
            raise HandEdit([heading])
    lines = content.split("\n")
    if sec is None:
        sec = Section(heading)
        later = ORDER[ORDER.index(heading) + 1 :] if heading in ORDER else ()
        pos = next((i for i, s in enumerate(note.sections) if s.heading in later), len(note.sections))
        note.sections.insert(pos, sec)
    sec.lines = lines
    hashes[heading] = digest(content)


def hand_edits(note: Note, headings: tuple[str, ...] = GENERATED) -> list[str]:
    hashes = note.data.get("_render") or {}
    out = []
    for h in headings:
        sec = note.section(h)
        if sec is not None and sec.content.strip() and hashes.get(h) and digest(sec.content) != hashes[h]:
            out.append(h)
    return out


def render(note: Note, table_html, force: bool = False) -> None:
    """Rebuild Ingredients, Method and the table from the data block, all or nothing."""
    recipe = recipe_of(note)
    wanted = {
        "Ingredients": ingredients_md(recipe.get("ingredients")),
        "Method": method_md(recipe.get("steps")),
        "Cooking for Engineers": cfe_md(recipe, table_html),
    }
    if not force:
        blocked = [h for h in hand_edits(note, RENDERED) if digest(wanted[h]) != digest(note.section(h).content)]  # type: ignore[union-attr]
        if blocked:
            raise HandEdit(blocked)
    for heading, content in wanted.items():
        set_section(note, heading, content, force=True)


# ---------- the recipe as one object ----------

def fmt_minutes(n: Any) -> str:
    try:
        m = int(round(float(n)))
    except (TypeError, ValueError):
        return ""
    if m <= 0:
        return ""
    h, m = divmod(m, 60)
    if not h:
        return f"{m} min"
    return f"{h} hr" + (f" {m} min" if m else "")


def notes_text(note: Note, limit: int = 400) -> str:
    sec = note.section("Notes")
    if not sec:
        return ""
    text = " ".join(re.sub(r"^\s*(?:[-*]|\d+\.)\s+", "", ln).strip() for ln in sec.lines if ln.strip())
    return text if len(text) <= limit else text[: limit - 1].rstrip() + "…"


def recipe_of(note: Note) -> dict[str, Any]:
    """The note as one recipe object in the Console card shape (plus cfe)."""
    fm = note.frontmatter
    serves = fm.get("yield") or ""
    if fm.get("servings") and not serves:
        serves = str(fm["servings"])
    elif fm.get("servings") and str(fm["servings"]) not in str(serves):
        serves = f"{fm['servings']} ({serves})"
    obj: dict[str, Any] = {"title": str(fm.get("title") or note.title)}
    if serves:
        obj["serves"] = str(serves)
    time = {k: fmt_minutes(fm.get(f"{k}_min")) for k in ("prep", "cook", "total")}
    time = {k: v for k, v in time.items() if v}
    if time:
        obj["time"] = time
    obj["ingredients"] = note.data.get("ingredients") or []
    obj["steps"] = note.data.get("steps") or []
    nt = notes_text(note)
    if nt:
        obj["notes"] = nt
    if note.data.get("cfe"):
        obj["cfe"] = note.data["cfe"]
    return obj


# ---------- files ----------

def safe_title(title: str) -> str:
    t = re.sub(r'[\\/:*?"<>|#^\[\]]', " ", title)
    return " ".join(t.split()).strip(" .") or "Untitled recipe"


def all_notes(folder: Path | None = None) -> list[Path]:
    folder = folder or RECIPES
    return sorted(p for p in folder.glob("*.md") if not p.name.startswith("."))


def resolve(name: str, folder: Path | None = None) -> Path:
    p = Path(name).expanduser()
    if p.suffix == ".md" and p.is_file():
        return p
    notes = all_notes(folder)
    key = name.strip().lower().removesuffix(".md")
    exact = [n for n in notes if n.stem.lower() == key]
    if exact:
        return exact[0]
    near = [n for n in notes if key in n.stem.lower()]
    if len(near) == 1:
        return near[0]
    if not near:
        raise FileNotFoundError(f"no recipe note matches {name!r} in {folder or RECIPES}")
    raise FileNotFoundError(f"{name!r} matches {len(near)} notes: " + ", ".join(n.stem for n in near))


def new_note(path: Path, frontmatter: dict[str, Any], data: dict[str, Any], description: str = "",
             notes: str = "") -> Note:
    sections = [Section(None, description.strip().split("\n") if description.strip() else [])]
    for h in ("Ingredients", "Method", "Cooking for Engineers"):
        sections.append(Section(h))
    sections.append(Section("Notes", notes.strip().split("\n") if notes.strip() else []))
    sections.append(Section("Cook log", [NO_COOKS]))
    return Note(path, dict(frontmatter), "", sections, dict(data), fm_changed=True)


def log_cook(note: Note, when: dt.date, rating: int | None, text: str) -> str:
    sec = note.section("Cook log")
    if sec is None:
        sec = Section("Cook log")
        note.sections.append(sec)
    parts = [when.isoformat()]
    if rating is not None:
        parts.append(f"{rating}/5")
    line = "- " + ": ".join([parts[0], " · ".join(parts[1:] + ([text.strip()] if text.strip() else []))]).rstrip(": ")
    body = [ln for ln in sec.lines if ln.strip() and ln.strip() != NO_COOKS]
    sec.lines = body + [line]
    fm = note.frontmatter
    fm["last_cooked"] = when
    fm["times_cooked"] = int(fm.get("times_cooked") or 0) + 1
    if rating is not None:
        fm["rating"] = rating
    if fm.get("status") in (None, "", "to-try"):
        fm["status"] = "tested"
    note.fm_changed = True
    return line
